    function deriveFacilityFromLegacy(){const selected=studyContext?.snapshot().current;if(selected?.studyKind!=='NETWORK_ORDERS'||!store||!facilityController)throw Object.assign(new Error('请先选择配送网络研究。'),{code:'LEGACY_STUDY_REQUIRED'});const active=store.activeRecord(),data=store.context.dataSource.facilityData||{};const loaded=facilityController.load(dependencies.FacilityMvp.fromScenario(active.scenario,{candidateSites:data.candidateSites||[],costParameters:data.costParameters||[],costPeriod:data.costPeriod||active.scenario.assumptions.costPeriod||'MODEL_RUN',currency:data.currency||active.scenario.assumptions.currency||'CNY'}));facilityInputHash=active.inputHash;facilitySavedPointer=null;selectFacilityCurrent();return loaded;}
