    function activeFocus() {
      const active = documentValue.activeElement;
      if (!active || !target?.contains(active)) return null;
      const attributes = ["designAction", "designId", "designResult", "designFinder", "designNote", "designScenarioFilter", "designCostScope", "designValidationStatus", "designDemandPeriod"];
      const dataset = Object.fromEntries(attributes.filter((key) => Object.prototype.hasOwnProperty.call(active.dataset || {}, key)).map((key) => [key, active.dataset[key]]));
      if (!Object.keys(dataset).length) return null;
      return { dataset, selectionStart: active.selectionStart, selectionEnd: active.selectionEnd };
    }
    function restoreActiveFocus(focus) {
      if (!focus || !target) return;
      const node = [...target.querySelectorAll("[data-design-action], [data-design-result], [data-design-finder], [data-design-note], [data-design-scenario-filter], [data-design-cost-scope], [data-design-validation-status], [data-design-demand-period]")].find((candidate) => Object.entries(focus.dataset).every(([key, value]) => candidate.dataset[key] === value));
      if (!node) return;
      node.focus();
      if (typeof node.setSelectionRange === "function" && Number.isInteger(focus.selectionStart)) node.setSelectionRange(focus.selectionStart, focus.selectionEnd);
    }
